    if (parcelas <= PARCELAS_SEM_JUROS) {
        return Dinheiro.arredondar(totalFinal.divide(BigDecimal.valueOf(parcelas), 10, RoundingMode.HALF_EVEN));
    }

    BigDecimal totalSemJuros = totalFinal.divide(
