                    )
                )
            ).divide(TAXA_JUROS, 10, RoundingMode.HALF_EVEN)
        ),
        10,
        RoundingMode.HALF_EVEN
    );

    return calcularValorParcelaComJuros(totalSemJuros, parcelas);
}

