    BigDecimal divisor = BigDecimal.ONE.subtract(fatorParcela);
    BigDecimal valorParcela = total.multiply(TAXA_JUROS).divide(divisor, 10, RoundingMode.HALF_EVEN);

    return Dinheiro.arredondar(valorParcela);
}

